"""Impairments"""
from __future__ import print_function, absolute_import, division,\
    unicode_literals
from builtins import object
import paramiko
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from taf.ul.trs_e2e_fw.lib.traffic.exceptions import *

from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.decorators import check_rat
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from future import standard_library
standard_library.install_aliases()
logger = BackgroundLogger.Instance()


class Impairments(object):
    """Impairments"""
    def __init__(self):
        # self.config = get_variables()
        self.config = ConfigHandler.get_config()

    @check_rat
    def traffic_impairments_generate(self, **kwargs):
        """
          Impairs packets using netem tool.
        :param impairment_device: should be device name as in
         testline_config.json impairments profile
        :param operation: can be loss, duplication, reorder
        :param profile : should be picked from test_case.json in
         impairments_profile
        :param kwargs: 'delay' in case of reorder,
        :return: None

        """
        operation = kwargs.pop('operation', '')
        profile = kwargs.pop('profile', None)
        impairment_device = kwargs.pop('impairment_device', 'netem')
        dest_ip = get_config_variable(["impairments_profile", profile,
                                       "dest_ip"])
        ethport = get_config_variable(["impairments_profile", profile,
                                       "ethport"])
        protocol = get_config_variable(["impairments_profile", profile,
                                        "protocol"])
        percent = get_config_variable(["impairments_profile", profile,
                                       "percent"])
        commands = get_config_variable(["impairments_profile", profile,
                                        "commands"])
        if operation.lower() == 'loss':
            delay = get_config_variable(["impairments_profile", profile,
                                         "delay"])
            self._generate_loss(impairment_device, dest_ip, ethport, protocol,
                                percent, delay)
        elif operation.lower() == 'duplication':
            self._generate_duplication(impairment_device, dest_ip, ethport,
                                       protocol, percent)
        elif operation.lower() == 'reorder':
            delay = get_config_variable(["impairments_profile", profile,
                                         "delay"])
            self._generate_reorder(impairment_device, dest_ip, ethport,
                                   protocol, percent, delay)
        elif operation == '':
            if len(commands) != 0:
                self._login_to_impairment_pc(impairment_device)
                self._run_netem_full_commands(ethport, commands)
            else:
                raise Exception(
                    'If Operation is not provided, commands param in profile'
                    ' should not be empty')

    @check_rat
    def traffic_impairment_stop(self, **kwargs):
        """Stop traffic impairment"""
        profile = kwargs.pop('profile', None)
        impairment_device = kwargs.pop('impairment_device', 'netem')
        ethport = get_config_variable(["impairments_profile", profile,
                                       "ethport"])
        self._login_to_impairment_pc(impairment_device)
        logger.debug("stopping traffic impairment....")
        self.ssh_session.exec_command("sudo tc qdisc del dev {} root".format(
            ethport))

    def _generate_loss(self, impairment_device, dest_ip, ethport, protocol,
                       packet_loss_percent, packet_delay):
        logger.debug("generating loss....")
        self._login_to_impairment_pc(impairment_device)
        protocol_num = self._get_protocol_number(protocol)
        self._run_netem_commands("loss", dest_ip, ethport, protocol_num,
                                 packet_loss_percent, packet_delay)

    def _generate_duplication(self, impairment_device, dest_ip, ethport,
                              protocol, packet_dup_percent):
        logger.debug("generating duplication....")
        self._login_to_impairment_pc(impairment_device)
        protocol_num = self._get_protocol_number(protocol)
        self._run_netem_commands("duplicate", dest_ip, ethport, protocol_num,
                                 packet_dup_percent)

    def _generate_reorder(self, impairment_device, dest_ip, ethport, protocol,
                          packet_reorder_percent, packet_delay):
        logger.debug("generating reorder.....")
        self._login_to_impairment_pc(impairment_device)
        protocol_num = self._get_protocol_number(protocol)
        self._run_netem_commands("reorder", dest_ip, ethport, protocol_num,
                                 packet_reorder_percent, packet_delay)

    def _login_to_impairment_pc(self, impairment_device):
        logger.debug("logging to impairment pc....")
        ip = get_config_variable(['impairments', impairment_device, 'ip'])
        user = get_config_variable(['impairments', impairment_device, 'user'])
        password = get_config_variable(['impairments', impairment_device,
                                        'password'])
        self.ssh_session = paramiko.SSHClient()
        self.ssh_session.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        self.ssh_session.connect(hostname=ip, username=user, password=password)
        # print ip, user, password

    def _run_netem_commands(self, operation, dest_ip, eth, protocol_num,
                            percent, packet_delay=0):
        logger.debug("executing netem commands....")
        self._exec_command("sudo tc qdisc del dev {} root".format(eth))
        self._exec_command("sudo tc qdisc add dev {} handle 1: root "
                           "htb".format(eth))
        self._exec_command("sudo tc class add dev {} parent 1: classid 1:1 htb"
                           " rate 1000Mbps".format(eth))
        self._exec_command("sudo tc class add dev {} parent 1:1 classid 1:11"
                           " htb rate 100Mbps".format(eth))
        self._exec_command(self._get_command(eth, operation, percent,
                                             packet_delay))
        cmd = "sudo tc filter add dev {} protocol ip parent 1:0 prio 1 u32 " \
              "match ip protocol {} 0xff match ip dst {}" \
              " flowid 1:11".format(eth, protocol_num, dest_ip)
        self._exec_command(cmd)
        self._exec_command("sudo tc qdisc list")
        self.ssh_session.close()

    def _run_netem_full_commands(self, eth, commands):
        logger.debug("executing netem full commands....")
        self._exec_command("sudo tc qdisc del dev {} root".format(eth))
        self._exec_command("sudo tc qdisc add dev {} handle 1: root"
                           " htb".format(eth))
        self._exec_command("sudo tc class add dev {} parent 1: classid 1:1 "
                           "htb rate 1000Mbps".format(eth))
        self._exec_command("sudo tc class add dev {} parent 1:1 classid 1:11"
                           " htb rate 100Mbps".format(eth))
        logger.debug("ting netem full commands....", commands)
        full_commands = commands.split(";")
        for cmd in full_commands:
            logger.debug("full commands....", cmd)
            self._exec_command(cmd)

        self._exec_command("sudo tc qdisc list")
        self.ssh_session.close()

    def _get_command(self, ethport, operation, percent, packet_delay):
        operation = operation.lower()
        if operation == "loss" or operation == "duplicate":
            return "sudo tc qdisc add dev {} parent 1:11 handle 10:0 " \
                   "netem {} {}%".format(ethport, operation, percent)
        elif operation == "reorder":
            return "sudo tc qdisc add dev {} parent 1:11 handle 10:0 netem " \
                   "gap 1 delay {}ms {} {}%". \
                format(ethport, packet_delay, operation, percent)

    def _get_protocol_number(self, protocol):
        logger.debug("get protocol number....")
        if protocol.lower() == 'udp':
            return 17
        elif protocol.lower() == 'tcp':
            return 6
        elif protocol.lower() == 'icmp':
            return 1
        elif protocol.lower() == 'sctp':
            return 132
        elif protocol.lower() == 'esp':
            return 50
        else:
            raise UnSupportedProtocolException(protocol)

    def _exec_command(self, cmd):
        print(cmd)
        std_in, std_out, std_err = self.ssh_session.exec_command(cmd)
        print(std_out.readlines())
